    // Cell data arrays
    const alive = new Uint8Array(rows * cols);
    const age = new Uint8Array(rows * cols);
    const dying = new Uint8Array(rows * cols); // 0: alive, 1: dying
    const dieTimer = new Uint8Array(rows * cols); // counts frames of fade

    // Emoji mapping based on age
    const emojis = ['🟢', '🟡', '🟠', '🔴', '❌'];
    const ageThreshold = [0, 2, 5, 8]; // thresholds for emoji indices

    // Patterns data
    const patternData = {
