// Bullet class
class Bullet {
  constructor(x, y, xdir, ydir, size, color) {
    this.x = x; this.y = y;
    this.xdir = xdir; this.ydir = ydir;
    this.size = size;
    this.color = color;
  }
  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
  update() {
    this.y += this.ydir;
    this.x += this.xdir;
  }
}

// Player class
class Player {
  constructor(x, y, w, h, c) {
    this.x = x; this.y = y;
    this.w = w; this.h = h;
    this.c = c;
    this.v = 5;
  }
  draw() {
    ctx.fillStyle = this.c; ctx.fillRect(this.x, this.y, this.w, this.h);
  }
  update() {
    if (keys["ArrowLeft"]) this.x -= this.v;
    if (keys["ArrowRight"]) this.x += this.v;
    if (this.x < 0) this.x = 0;
    if (this.x + this.w > W) this.x = W - this.w;
  }
}

// Invader class
class Invader {
  constructor(x, y, w, h, c, speed) {
    this.x = x; this.y = y;
    this.w = w; this.h = h;
    this.c = c;
    this.speed = speed;
  }
  draw() {
    ctx.fillStyle = this.c; ctx.fillRect(this.x, this.y, this.w, this.h);
  }
  update() {
    this.x += this.speed;
    if (this.x + this.w > W || this.x < 0) {
      this.speed *= -1;
      this.y += invaderHeight + 10;
    }
  }
}

// Explosion class
class Explosion {
  constructor(x, y, frames, size, img) {
    this.x = x; this.y = y;
    this.frames = frames;
    this.size = size;
    this.img = img;
    this.frame = 0;
  }
  draw() {
    ctx.drawImage(
      this.img,
      this.frame * explosionSize, 0,
      explosionSize, explosionSize,
      this.x, this.y,
      this.size, this.size
    );
  }
  update() {
    this.frame += 1;
    if (this.frame === this.frames) gameObjects = gameObjects.filter(o => o instanceof Explosion && o !== this);
  }
}

// On canvas clicked event
canvas.addEventListener("click", e => {
  if (paused) {
    // Resume game
    paused = false;
    document.removeEventListener("click", this);
  }
  else if (gameOver) {
    // Restart game
    setup();
  }
});
canvas.addEventListener("mousemove", e => {
