  explosionImg.src = "explosion.png";
}

function setup() {
  initSprites();

  document.body.style.overflow = "hidden";
  document.documentElement.style.overflow = "hidden";
  document.body.style.cursor = "none";

  gameObjects = [];

  const player = new Player(W / 2, H - playerHeight * 2, playerWidth, playerHeight, "#fff");
  gameObjects.push(player);

  let x = (W - invaderWidth * 10) / 2;
  for (let y = 50; y < H - 50; y += invaderHeight * 2 + invaderHeight / 2) {
    for (let i = 0; i < 11; i++) {
      gameObjects.push(new Invader(x, y, invaderWidth, invaderHeight, "#fff", Math.random() < 0.5 ? -2 : 2));
      x += invaderWidth * 2 + invaderWidth / 2;
    }
    x = (W - invaderWidth * 10) / 2;
  }

  lives = 3; score = 0; level = 1;
  paused = false; gameOver = false;

  livesText = document.createElement("div");
  livesText.innerText = `Lives: ${lives}`;
  document.body.appendChild(livesText);

  scoreText = document.createElement("div");
  scoreText.innerText = `Score: ${score}`;
  document.body.appendChild(scoreText);
}

// Game loop
function loop() {
  if (paused) return;
  ctx.clearRect(0, 0, W, H);

  // Update gameobjects
  for (let i = gameObjects.length - 1; i >= 0; i--) {
    const obj = gameObjects[i];
    if (obj instanceof Player) {
      obj.update();
      if (obj.y > H) {
        lives--;
        livesText.innerText = `Lives: ${lives}`;
        setup();
        break;
      }
    } else if (obj instanceof Invader) {
      obj.update();
      if (obj.y > H) {
        gameOver = true;
        break;
      }
    } else if (obj instanceof Bullet) {
      obj.update();
      if (obj.y < 0) gameObjects = gameObjects.filter(b => b !== obj);
    }
    // Check collision with player
    if (!gameOver && (obj instanceof Bullet || obj instanceof Invader) && obj.x >= obj.x && obj.x + obj.w <= obj.x && obj.y >= obj.y && obj.y + obj.h <= obj.y) {
      if (obj instanceof Bullet) score++;
      else {
        gameObjects = gameObjects.filter(b => b !== obj);
        gameObjects.push(new Explosion(obj.x, obj.y, explosionFrames, explosionSize, explosionImg));
      }
      if (score % 500 === 0) level++;
      scoreText.innerText = `Score: ${score}`;
      if (obj instanceof Invader && gameObjects.every(o => o instanceof Invader && o.y !== H)) {
        setup();
        break;
      }
    }
  }
  // Draw gameobjects
  for (const obj of gameObjects) obj.draw();

  if (gameOver) {
    document.body.style.cursor = "auto";
    scoreDisplay = document.createElement("div");
    scoreDisplay.innerText = `GAME OVER! Your score was ${score}. Click to restart.`;
    document.body.appendChild(scoreDisplay);
  }

  requestAnimationFrame(loop);
}

setup();
loop();
}
