                    score += 10;
                    playerBullets.splice(i,1);
                    break;
                }
            }
        }
        for (var i = enemyBullets.length - 1; i >= 0; i--) {
            var eb = enemyBullets[i];
            if (rectIntersect(eb, player)) {
                gameState = 'lose';
                break;
            }
        }

        // Check win
        if (enemies.every(function(e){return !e.alive;})) {
            level++;
            enemySpeed += 0.2;
            enemyShotInterval = Math.max(500, enemyShotInterval - 150);
            createEnemies();
            playerBullets.length = 0;
            enemyBullets.length = 0;
        }

        // Check lose enemies reach bottom
        for (var i = 0; i < enemies.length; i++) {
            var e = enemies[i];
            if (e.alive && e.y + e.h >= canvas.height - 20) {
                gameState = 'lose';
                break;
            }
        }

        // Explosions
        for (var i = explosions.length - 1; i >= 0; i--) {
            var ex = explosions[i];
            ex.r += 2;
            if (ex.r > 20) explosions.splice(i,1);
        }
    }

    function draw() {
        ctx.fillStyle = 'black';
        ctx.fillRect(0,0,canvas.width,canvas.height);

        // Draw player
        ctx.fillStyle = 'lime';
        ctx.beginPath();
        ctx.moveTo(player.x + player.w/2, player.y);
        ctx.lineTo(player.x, player.y + player.h);
        ctx.lineTo(player.x + player.w, player.y + player.h);
        ctx.closePath();
        ctx.fill();

        // Draw enemies
        ctx.fillStyle = 'red';
        for (var i = 0; i < enemies.length; i++) {
            var e = enemies[i];
            if (!e.alive) continue;
            ctx.fillRect(e.x, e.y, e.w, e.h);
        }

        // Draw bullets
        ctx.fillStyle = 'yellow';
        for (var i = 0; i < playerBullets.length; i++) {
            var b = playerBullets[i];
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }
        ctx.fillStyle = 'orange';
        for (var i = 0; i < enemyBullets.length; i++) {
            var b = enemyBullets[i];
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }

        // Draw explosions
        for (var i = 0; i < explosions.length; i++) {
            var ex = explosions[i];
            ctx.fillStyle = 'rgba(255,165,0,' + (1 - ex.r/20) + ')';
            ctx.beginPath();
            ctx.arc(ex.x, ex.y, ex.r, 0, Math.PI*2);
            ctx.fill();
        }

        // Draw score and level
        ctx.fillStyle = 'white';
        ctx.font = '16px Arial';
        ctx.fillText('Score: ' + score, 10, 20);
        ctx.fillText('Level: ' + level, 400, 20);

        if (gameState === 'lose') {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0,0,canvas.width,canvas.height);
            ctx.fillStyle = 'white';
            ctx.font = '48px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Game Over', canvas.width/2, canvas.height/2);
            ctx.font = '24px Arial';
            ctx.fillText('Press Enter to Restart', canvas.width/2, canvas.height/2 + 40);
        }
    }

    function loop() {
        update();
        draw();
        requestAnimationFrame(loop);
    }
    document.addEventListener('keydown', function(e) {
        if (gameState === 'lose' && e.code === 'Enter') {
            resetGame();
        }
    });
    requestAnimationFrame(loop);
