async function generateAndSolveMaze(canvasId) {
  try {
    const canvas = document.getElementById(canvasId);
    if (!canvas || canvas.width !== 500 || canvas.height !== 500)
      throw new Error('Canvas must exist and be 500x500 pixels');
    const ctx = canvas.getContext('2d');
    const CELL_SIZE = 20;
    const COLS = Math.floor(canvas.width / CELL_SIZE);
    const ROWS = Math.floor(canvas.height / CELL_SIZE);
    // Grid values: 0=wall,1=path,2=search,3=solution
    const grid = Array.from({ length: ROWS }, () => Array(COLS).fill(1));

    // Outer walls
    for (let i = 0; i < ROWS; i++) {
      grid[i][0] = 0;
      grid[i][COLS - 1] = 0;
    }
    for (let j = 0; j < COLS; j++) {
      grid[0][j] = 0;
      grid[ROWS - 1][j] = 0;
    }

    const start = { x: 1, y: 1 };
    const goal = { x: COLS - 2, y: ROWS - 2 };

    const randomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
    const sleep = ms => new Promise(r => setTimeout(r, ms));

    const draw = () => {
      for (let y = 0; y < ROWS; y++) {
        for (let x = 0; x < COLS; x++) {
          let color;
          if (grid[y][x] === 0) color = '#000';
          else if (grid[y][x] === 1) color = '#fff';
          else if (grid[y][x] === 2) color = '#00f';
          else if (grid[y][x] === 3) color = '#f00';
          else color = '#fff';
          if (x === start.x && y === start.y) color = '#0f0';
          if (x === goal.x && y === goal.y) color = '#ffa500';
          ctx.fillStyle = color;
          ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
      }
    };

    async function generateMaze(x, y, w, h) {
      if (w <= 1 || h <= 1) return;
      const horizontal = Math.random() < 0.5;
      if (horizontal) {
        const wallRow = randomInt(y + 1, y + h - 2);
        for (let col = x; col < x + w; col++) grid[wallRow][col] = 0;
        const passageCol = randomInt(x, x + w - 1);
        grid[wallRow][passageCol] = 1;
        await draw();
        await sleep(20);
        await generateMaze(x, y, w, wallRow - y);
        await generateMaze(x, wallRow + 1, w, y + h - 1 - wallRow);
      } else {
        const wallCol = randomInt(x + 1, x + w - 2);
        for (let row = y; row < y + h; row++) grid[row][wallCol] = 0;
        const passageRow = randomInt(y, y + h - 1);
        grid[passageRow][wallCol] = 1;
        await draw();
        await sleep(20);
        await generateMaze(x, y, wallCol - x, h);
        await generateMaze(wallCol + 1, y, x + w - 1 - wallCol, h);
      }
    }

    // Generate maze
    await draw();
    await generateMaze(start.x, start.y, COLS - 2, ROWS - 2);
    grid[start.y][start.x] = 1;
    grid[goal.y][goal.x] = 1;

    // A* search
    const open = [{ x: start.x, y: start.y, g: 0, h: 0, f: 0, parent: null }];
    const closed = new Set();
    const nodes = Array.from({ length: ROWS }, () => Array(COLS).fill(null));

    const finalizeSolution = () => {
      let node = open[0];
      while (node.parent) {
        if (!(node.x === start.x && node.y === start.y))
          grid[node.y][node.x] = 3;
        node = node.parent;
      }
    };

    await (async () => {
      while (open.length) {
        let idx = 0;
        for (let i = 1; i < open.length; i++)
          if (open[i].f < open[idx].f) idx = i;
        const current = open.splice(idx, 1)[0];
        closed.add(`${current.x},${current.y}`);
        if (!(current.x === start.x && current.y === start.y) &&
            !(current.x === goal.x && current.y === goal.y))
          grid[current.y][current.x] = 2;
        await draw();
        await sleep(10);
        if (current.x === goal.x && current.y === goal.y) {
          nodes[current.y][current.x] = current;
          finalizeSolution();
          break;
        }
        const dirs = [
          [1, 0],
          [-1, 0],
          [0, 1],
          [0, -1],
        ];
        for (const [dx, dy] of dirs) {
          const nx = current.x + dx,
            ny = current.y + dy;
          if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
          if (grid[ny][nx] === 0) continue;
          const key = `${nx},${ny}`;
          if (closed.has(key)) continue;
          const g = current.g + 1;
          const h = Math.abs(nx - goal.x) + Math.abs(ny - goal.y);
          const f = g + h;
          let node = nodes[ny][nx];
          if (!node || g < node.g) {
            node = { x: nx, y: ny, g, h, f, parent: current };
            nodes[ny][nx] = node;
            open.push(node);
          }
        }
      }
      await draw();
    })();
  } catch (err) {
    console.error(err);
  }
